MERGE INTO INFRANEXUM_IAM_PERMISSION p USING (SELECT '019ffbda-1060-7001-8001-000000000001' ID,'itam.asset.read' CODE,'read' ACTION_NAME,'NORMAL' SENSITIVITY FROM dual UNION ALL SELECT '019ffbda-1061-7002-8002-000000000002','itam.asset.create','create','ELEVATED' FROM dual UNION ALL SELECT '019ffbda-1062-7003-8003-000000000003','itam.asset.update','update','ELEVATED' FROM dual) s ON (p.CODE=s.CODE AND p.ORGANIZATION_ID IS NULL) WHEN NOT MATCHED THEN INSERT (ID,ORGANIZATION_ID,CODE,RESOURCE_TYPE,ACTION_NAME,SENSITIVITY,SCOPE_KIND,SYSTEM_DEFINED,ACTIVE,CREATED_AT,UPDATED_AT,DELETED_AT) VALUES (s.ID,NULL,s.CODE,'itam_asset',s.ACTION_NAME,s.SENSITIVITY,'ORGANIZATION',1,1,SYSTIMESTAMP,SYSTIMESTAMP,NULL);
MERGE INTO INFRANEXUM_IAM_ROLE_PERMISSION rp USING (SELECT '019ffbda-1001-7e80-9ec8-7580467e9a85' ROLE_ID,ID PERMISSION_ID FROM INFRANEXUM_IAM_PERMISSION WHERE ORGANIZATION_ID IS NULL AND CODE IN ('itam.asset.read','itam.asset.create','itam.asset.update')) s ON (rp.ROLE_ID=s.ROLE_ID AND rp.PERMISSION_ID=s.PERMISSION_ID) WHEN NOT MATCHED THEN INSERT (ROLE_ID,PERMISSION_ID) VALUES (s.ROLE_ID,s.PERMISSION_ID);
